// Build final player list: sets in order, players shuffled within each set
export function buildMegaAuctionPlayers() {
  return MEGA_AUCTION_SETS.flatMap(set => {
    const players = [...set.players];
    for (let i = players.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [players[i], players[j]] = [players[j], players[i]];
    }
    return players;
  });
}

